tosedo show(ds)
    sheye top <- louwo(ds) - 1;
    veshim ((top > 0) dilisyo (top >= 0)) {
        wesosa (ds[top] <> 0) {
            bou;
        }
        top <- top - 1;
    }
    sheye r <- "";
    sho (sheye i <- top; i >= 0; i <- i - 1) {
        r <- r + ds[i];
    }
    cha r;
bawoum tosedo

tosedo add(a, b)
    sheye r <- [];
    sheye carry <- 0;
    sheye n <- louwo(a);
    wesosa (louwo(b) > n) {
        n <- louwo(b);
    }
    sho (sheye i <- 0; i < n; i <- i + 1) {
        sheye s <- carry;
        wesosa (i < louwo(a)) {
            s <- s + a[i];
        }
        wesosa (i < louwo(b)) {
            s <- s + b[i];
        }
        omse(r, s drossou 10);
        carry <- s / 10;
    }
    omse(r, carry);
    cha r;
bawoum tosedo

tosedo mul(a, b)
    sheye r <- [];
    sho (sheye i <- 0; i < (louwo(a) + louwo(b)); i <- i + 1) {
        omse(r, 0);
    }
    sho (sheye i <- 0; i < louwo(a); i <- i + 1) {
        sheye carry <- 0;
        sheye ai <- a[i];
        sho (sheye j <- 0; j < louwo(b); j <- j + 1) {
            sheye cur <- (r[i + j] + (ai * b[j])) + carry;
            r[i + j] <- cur drossou 10;
            carry <- cur / 10;
        }
        sheye k <- i + louwo(b);
        veshim (carry > 0) {
            sheye cur2 <- r[k] + carry;
            r[k] <- cur2 drossou 10;
            carry <- cur2 / 10;
            k <- k + 1;
        }
    }
    cha r;
bawoum tosedo

